 public static void Run(Application app,Action<bool,string> check,ImageBinaryPlugin plugin,GrayImage input,NodeDocument node,Dictionary<string,JsonElement> values){SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(app.Dispatcher));var samples=new List<RoiDocument>{new("rect",RoiKind.Rectangle,100,100,80,60),new("upright",RoiKind.UprightRectangle,100,100,80,60),new("circle",RoiKind.Circle,100,100,Radius:40),new("ring",RoiKind.SectorRing,100,100,Radius:40,InnerRadius:20),new("sector",RoiKind.Sector,100,100,Radius:40,InnerRadius:20){Shape=new(StartAngle:-30,SweepAngle:120)},new("over",RoiKind.OverSector,100,100,Radius:40,InnerRadius:20){Shape=new(SweepAngle:450)},new("point",RoiKind.Point,100,100),new("line",RoiKind.Line,40,70){Shape=new(EndX:160,EndY:110)},new("line-caliper",RoiKind.LineCaliper,40,70){Shape=new(EndX:160,EndY:110,CaliperCount:6,CaliperWidth:12,CaliperHeight:20)},new("circle-caliper",RoiKind.CircleCaliper,100,100,Radius:40){Shape=new(CaliperCount:30,CaliperWidth:5,CaliperHeight:20)},new("sector-caliper",RoiKind.SectorCaliper,40,70,Radius:80){Shape=new(EndX:160,EndY:110,CaliperCount:6,CaliperWidth:12,CaliperHeight:20)},new("matrix",RoiKind.MatrixCircle,100,100,80,60,Radius:10,InnerRadius:6),new("coordinate",RoiKind.Coordinate,100,100),new("box3d",RoiKind.Box3D,100,100,80,60){Shape=new(Depth:100)},new("poly",RoiKind.Polygon,0,0,Vertices:[new(40,40),new(140,30),new(160,140),new(50,160)])};var pixels=Enumerable.Range(0,256*256).Select(i=>(byte)(i%256)).ToArray();var image=new GrayImage(256,256,pixels);foreach(var sample in samples){var view=new GroupRoiEditor([sample],new([sample.Kind],FullImage:false)){ParametersExpanded=true};view.SetImage(image);var border=new Border{Background=new SolidColorBrush(Color.FromRgb(242,243,245)),Child=view};var gallery=new Window{Content=border,Width=1080,Height=700,FontFamily=new("Microsoft YaHei UI"),FontSize=14,ShowInTaskbar=false,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual,Left=-20000,Top=-20000};gallery.Show();Pump(gallery);check(Children(view).OfType<TextBox>().Count(t=>(t.Tag as string)?.StartsWith("GroupRoiField:")==true)==RoiParameterTemplates.Fields(sample).Count,"native parameter field template "+sample.Kind);view.CommitPending();Capture(border,"roi-template-"+sample.Kind+".png");if(sample.Kind!=RoiKind.Box3D){var draw=new GroupRoiEditor([],new([sample.Kind],FullImage:false));draw.SetDrawKind(sample.Kind);if(sample.Kind==RoiKind.Polygon){foreach(var p in new[]{new Point(20,20),new Point(70,20),new Point(60,80)})draw.BeginPointer(p);draw.CompletePolygon();}else if(RoiWpfGeometry.IsLine(sample.Kind)){draw.PressPointer(new(40,50));draw.ReleasePointer(new(40,50));check(draw.Regions.Count==0,"native two-click line gesture remains pending after first release "+sample.Kind);draw.UpdatePointer(new(160,120));draw.PressPointer(new(160,120));draw.ReleasePointer(new(160,120));}else{draw.BeginPointer(new(40,50));draw.UpdatePointer(new(160,120));draw.EndPointer(new(160,120));}check(draw.Regions.Count==1&&draw.Regions[0].Kind==sample.Kind,"actual pointer draw "+sample.Kind);}gallery.Close();}
 var parameterRanges=plugin.Descriptor.Parameters.ToDictionary(p=>p.Name);check(parameterRanges["KernelWidth"].Minimum==1&&parameterRanges["KernelWidth"].Maximum==51&&parameterRanges["GaussSigma"].Minimum==.1&&parameterRanges["GaussSigma"].Maximum==100&&parameterRanges["ThresholdOffset"].Minimum==-255&&parameterRanges["ThresholdOffset"].Maximum==255&&parameterRanges["SauvolaAdjustCoef"].Minimum==-1&&parameterRanges["SauvolaAdjustCoef"].Maximum==1&&parameterRanges["SauvolaRange"].Minimum==.1&&parameterRanges["SauvolaRange"].Maximum==255&&parameterRanges["SauvolaWinWidth"].Minimum==1&&parameterRanges["SauvolaWinWidth"].Maximum==100,"mode parameter bounds match original AlgorithmTab XML");
 foreach(var kind in new[]{RoiKind.LineCaliper,RoiKind.CircleCaliper,RoiKind.SectorCaliper}){var sample=samples.Single(r=>r.Kind==kind);var edit=new GroupRoiEditor([sample],new([kind],FullImage:false));edit.SetImage(image);var editWindow=new Window{Content=edit,Width=1080,Height=700,ShowInTaskbar=false,ShowActivated=false,Left=-20000,Top=-20000,WindowStartupLocation=WindowStartupLocation.Manual};editWindow.Show();Pump(editWindow);var geometry=RoiWpfGeometry.ActiveCaliper(sample);double a=geometry.Angle*Math.PI/180;var handle=RoiWpfGeometry.CaliperHandles(sample)[0];var target=geometry.Center+new Vector(Math.Cos(a),Math.Sin(a))*15;edit.BeginPointer(handle);edit.UpdatePointer(target);edit.EndPointer(target);check(Math.Abs(RoiGeometry.Parameters(edit.Regions.Single()).CaliperWidth-30)<.001,"native caliper width drag changes actual geometry "+kind);editWindow.Close();}
 var current=node with{Parameters=values.ToDictionary(p=>p.Key,p=>p.Value.Clone()),Rois=[]};int writes=0;var runtime=plugin.CreateRuntime();using var neverCancel=new CancellationTokenSource();var session=new ToolDebugSession(async(parameters,token)=>{await Task.Yield();var result=await runtime.ExecuteAsync(new(current.Id,".",new Dictionary<string,PortValue>{{"Image",PortValue.Image(input)}},parameters,current.Rois),token);return new NodeRunRecord(current.Id,result.Status==ModuleStatus.Success?NodeRunStatus.Success:NodeRunStatus.Failed,result.Outputs,0,result.ErrorCode,result.Message);},20); // disposed explicitly below
 var context=new ToolEditorContext(current,".",p=>current=current with{Parameters=p},p=>session.RunOnceAsync(p)){Session=session,PreviewImage=()=>input,ApplyConfiguration=(p,r)=>{writes++;current=current with{Parameters=p.ToDictionary(p=>p.Key,p=>p.Value.Clone()),Rois=r.ToArray()};}};
  var window=(ImageBinaryWindow)plugin.CreateWpfEditor(context);window.Left=-20000;window.Top=-20000;window.WindowStartupLocation=WindowStartupLocation.Manual;window.Show();Pump(window);window.Roi.SetDrawKind(RoiKind.Sector);window.Roi.BeginPointer(new(8,8));window.Roi.UpdatePointer(new(14,8));window.Roi.EndPointer(new(14,8));check(writes>0&&current.Rois!.Single().Kind==RoiKind.Sector,"full native-layout window pointer commits actual tool geometry immediately");var tabs=Children(window).OfType<TabControl>().Single(t=>Equals(t.Tag,"ImageBinaryParameterTabs"));check(Math.Abs(tabs.ActualWidth-380)<2,"source screenshot layout reconstructs a 380-DIP parameter pane");tabs.SelectedIndex=1;Pump(window);ComboBox ModePicker()=>Children(window).OfType<ComboBox>().Single(t=>Equals(t.Tag,"ImageBinaryMode"));void SelectMode(int mode){var picker=ModePicker();picker.SelectedItem=picker.Items.OfType<ComboBoxItem>().Single(i=>Equals(i.Tag,mode));Pump(window);}bool HasField(string name)=>Children(window).OfType<FrameworkElement>().Any(t=>Equals(t.Tag,"ImageBinaryField:"+name));var choices=ModePicker().Items.OfType<ComboBoxItem>().ToArray();check(choices.Select(i=>(int)i.Tag).SequenceEqual(new[]{1,2,3,8,4})&&choices.All(i=>i.IsEnabled),"all five source-implemented BinaryType enum choices remain enabled");SelectMode(2);check(HasField("KernelWidth")&&HasField("KernelHeight")&&HasField("CompareType")&&HasField("ThresholdOffset")&&!HasField("LowThreshold"),"Mean mode follows original XML field-visibility trigger");var kernel=Children(window).OfType<TextBox>().Single(t=>Equals(t.Tag,"ImageBinaryField:KernelWidth"));kernel.Text="3.5";Wait(window.RunAsync(),window);check(current.Parameters["KernelWidth"].GetInt32()==3,"fractional text is rejected for an original integer parameter");kernel.Text="3";SelectMode(3);check(HasField("GaussKernelSize")&&HasField("GaussSigma")&&HasField("CompareType")&&HasField("ThresholdOffset")&&!HasField("KernelWidth"),"Gaussian mode follows original XML field-visibility trigger");SelectMode(8);check(HasField("SauvolaAdjustCoef")&&HasField("SauvolaRange")&&HasField("SauvolaSegType")&&HasField("SauvolaWinWidth")&&HasField("SauvolaWinHeight"),"Sauvola mode follows original XML field-visibility trigger");SelectMode(4);check(!HasField("LowThreshold")&&!HasField("KernelWidth")&&!HasField("GaussKernelSize")&&!HasField("SauvolaAdjustCoef"),"automatic mode hides source-triggered parameter fields");SelectMode(1);var low=Children(window).OfType<TextBox>().Single(t=>Equals(t.Tag,"ImageBinaryField:LowThreshold"));low.Text="80";low.RaiseEvent(new System.Windows.Input.KeyEventArgs(System.Windows.Input.Keyboard.PrimaryDevice,System.Windows.Input.Keyboard.PrimaryDevice.ActiveSource,0,System.Windows.Input.Key.Enter){RoutedEvent=System.Windows.Input.Keyboard.PreviewKeyDownEvent});check(current.Parameters["LowThreshold"].GetInt32()==80,"native numeric Enter commits actual runtime parameter");Wait(window.RunAsync(),window);check(window.LastResult?.Status==NodeRunStatus.Success,"actual full debug window executes real ROI algorithm");Capture((FrameworkElement)window.Content,"roi-binary-native-debug-window.png");var repeat=window.RunContinuousAsync();for(int i=0;i<20&&!repeat.IsCompleted;i++){Pump(window);Thread.Sleep(10);}Wait(session.StopAsync(),window);Wait(repeat,window);check(session.State==ToolDebugState.Idle,"continuous execution stops without retained session task");window.Close();Wait(session.DisposeAsync().AsTask(),window);
